    }
  }

  showWhileFiltering() {
    if (this.inputTarget.value) {
      this.#expandAll();
    } else {
      this.#restoreToggles()
    }
  }

  #expandAll() {
    this.sectionTargets.forEach(section => {
      section.setAttribute("data-is-filtering", true)
      section.open = true
    })
  }

